   float raw=commonSpan(width,height)/HEAD_SPAN[first];
   for(int i=first;i<first+6;i++)raw=Math.min(raw,Math.min(Math.max(1,width-6)/FullBodyRealisticFeatures.ALL[i][0],height/FullBodyRealisticFeatures.ALL[i][1]));
